import sys
import math
from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def minimal_prime_factor(n, limit):
    if n % 2 == 0:
        return 2 if 2 <= limit else n
    max_limit = min(limit, int(math.isqrt(n)) + 1)
    if max_limit < 2:
        return n if n > 1 else None
    for i in range(3, max_limit + 1, 2):
        if i > max_limit:
            break
        if n % i == 0:
            return i if i <= limit else n
    if limit >= math.isqrt(n) + 1:
        return n if n >= limit else None
    elif n <= limit:
        return n
    else:
        return n  # n is either prime larger than limit or alreadyTrail divisions failed

def compute_max_k(n_plus_1):
    current_lcm = 1
    max_k = 0
    for k in range(2, n_plus_1 + 1):
        if current_lcm * k > n_plus_1:
            break
        current_lcm = lcm(current_lcm, k)
        max_k = k
    return max_k

def check_condition(n, k, lcm_val):
    if k > 0:
        spf_min = minimal_prime_factor(n, k)
        if spf_min is not None:
            if spf_min <= k:
                return False
    if lcm_val == 0:
        return False
    if (n + 1) % lcm_val != 0:
        return False
    return True

def main():
    n, k = map(int, sys.stdin.readline().split())

    if k > n:
        print("No")
        return

    upper_bound = (n + 1) // 2
    if k > upper_bound:
        print("No")
        return

    if n == 1:
        print("No")
        return

    n_plus_1 = n + 1
    max_possible_k = compute_max_k(n_plus_1)
    effective_k = min(max_possible_k, upper_bound)

    found = False
    for test_k in range(1, effective_k + 1):
